import { readFileSync } from "node:fs";
import { describe, expect, it } from "vitest";

// The Supabase client is generated by Lovable and can be regenerated at any
// time. This test prevents silently pinning it to a hosted production project
// and then accidentally sending synthetic local acceptance logins there.
describe("Supabase client environment isolation", () => {
  it("allows environment-selected URL and publishable key rather than hardcoding the hosted project as the sole destination", () => {
    const source = readFileSync(new URL("./client.ts", import.meta.url), "utf8");
    expect(source).toMatch(/import\.meta\.env\.VITE_SUPABASE_URL/);
    expect(source).toMatch(/import\.meta\.env\.VITE_SUPABASE_PUBLISHABLE_KEY/);
    expect(source).toContain("createClient<Database>(SUPABASE_URL, SUPABASE_PUBLISHABLE_KEY");
  });

  it("keeps browser acceptance bound to local Supabase and blocks remote fixture traffic", () => {
    const acceptance = readFileSync(new URL("../../../e2e/authenticated-flow.pw.ts", import.meta.url), "utf8");
    const network = readFileSync(new URL("../../../e2e/nonproduction-network.ts", import.meta.url), "utf8");
    expect(acceptance).toContain("requireLocalOnlyRequests(page.context())");
    expect(acceptance).toContain('toBe("http://127.0.0.1:54321")');
    expect(network).toContain('["127.0.0.1", "localhost"]');
    expect(network).toContain("route.abort()");
  });
});
